<?phpsession_start();require_once "db.php";if (!isset($_SESSION['admin_id'])) {    header("Location: index.php");    exit();}$message = "";$messageType = "success";// Mark Attendanceif (isset($_POST['mark_attendance'])) {    $student_id = (int)($_POST['student_id'] ?? 0);    $subject_id = (int)($_POST['subject_id'] ?? 0);    $teacher_id = (int)($_POST['teacher_id'] ?? 0);    $date = $_POST['attendance_date'] ?? '';    $status = $_POST['status'] ?? '';    if (        $student_id <= 0 ||        $subject_id <= 0 ||        $teacher_id <= 0 ||        $date === '' ||        !in_array($status, ['Present', 'Absent'], true)    ) {        $message = "Please fill all attendance details correctly.";        $messageType = "error";    } else {        $sql = "INSERT INTO attendance        (student_id, subject_id, teacher_id, attendance_date, status)        VALUES ($1, $2, $3, $4, $5)        ON CONFLICT (student_id, subject_id, attendance_date)        DO UPDATE SET        teacher_id = EXCLUDED.teacher_id,        status = EXCLUDED.status";        $result = pg_query_params($conn, $sql, [            $student_id,            $subject_id,            $teacher_id,            $date,            $status        ]);        if ($result) {            $message = "Attendance Saved Successfully!";        } else {            $message = "Error saving attendance. " . pg_last_error($conn);            $messageType = "error";        }    }}// Get Students$students = pg_query(    $conn,    "SELECT student_id, student_name, roll_number     FROM students     ORDER BY student_name");// Get Subjects$subjects = pg_query(    $conn,    "SELECT subject_id, subject_name     FROM subjects     ORDER BY subject_name");// Get Teachers$teachers = pg_query(    $conn,    "SELECT teacher_id, teacher_name     FROM teachers     ORDER BY teacher_name");// Attendance Records$records = pg_query(    $conn,    "SELECT a.*, s.student_name, s.roll_number,            sub.subject_name, t.teacher_name     FROM attendance a     JOIN students s ON a.student_id = s.student_id     JOIN subjects sub ON a.subject_id = sub.subject_id     JOIN teachers t ON a.teacher_id = t.teacher_id     ORDER BY a.attendance_date DESC, a.attendance_id DESC");function e($value) {    return htmlspecialchars((string)$value, ENT_QUOTES, 'UTF-8');}?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>SmartAttend | Attendance Management</title><style>* {    margin: 0;    padding: 0;    box-sizing: border-box;    font-family: Arial, sans-serif;}body {    background: #0875c9;    min-height: 100vh;    color: #263653;}.header {    text-align: center;    color: white;    padding: 30px 15px;    position: relative;}.header h1 {    font-size: 32px;}.back {    position: absolute;    top: 25px;    left: 25px;    color: white;    text-decoration: none;    background: rgba(255,255,255,0.15);    padding: 11px 17px;    border-radius: 8px;}.back:hover {    background: rgba(255,255,255,0.28);}.attendance-layout {    display: grid;    grid-template-columns: 270px 1fr;    gap: 22px;    max-width: 1500px;    margin: 15px auto;    padding: 0 25px 40px;    align-items: start;}.attendance-form,.attendance-table {    background: white;    border-radius: 15px;    padding: 23px;    box-shadow: 0 5px 20px rgba(0,0,0,0.10);}.attendance-form h2,.attendance-table h2 {    font-size: 21px;    margin-bottom: 20px;}.attendance-form label {    display: block;    font-size: 14px;    font-weight: bold;    color: #536078;    margin: 15px 0 9px;}.attendance-form input,.attendance-form select {    width: 100%;    padding: 12px;    border: 1px solid #dce2eb;    border-radius: 8px;    outline: none;    background: white;    font-size: 14px;}.attendance-form input:focus,.attendance-form select:focus {    border-color: #1596d2;}.save-btn {    width: 100%;    padding: 14px;    margin-top: 22px;    background: #1596d2;    color: white;    border: none;    border-radius: 8px;    font-size: 15px;    font-weight: bold;    cursor: pointer;}.save-btn:hover {    background: #0875b5;}.message {    padding: 11px;    border-radius: 7px;    margin-bottom: 15px;    font-size: 13px;    line-height: 1.5;}.success {    background: #dcfce7;    color: #166534;}.error {    background: #fee2e2;    color: #991b1b;}.table-responsive {    width: 100%;    overflow-x: auto;}table {    width: 100%;    border-collapse: collapse;    min-width: 750px;}th {    background: #159bd1;    color: white;    padding: 14px 12px;    text-align: left;    font-size: 14px;}td {    padding: 14px 12px;    border-bottom: 1px solid #e9edf2;    font-size: 13px;}tr:hover {    background: #f5faff;}.present {    color: #16803d;    font-weight: bold;}.absent {    color: #dc2626;    font-weight: bold;}.edit-btn {    display: inline-block;    padding: 8px 13px;    background: #16a34a;    color: white;    text-decoration: none;    border-radius: 6px;    font-size: 13px;}.edit-btn:hover {    background: #15803d;}.empty {    text-align: center;    padding: 25px;    color: #8991a0;}@media(max-width: 900px) {    .attendance-layout {        grid-template-columns: 1fr;    }    .attendance-form {        max-width: 100%;    }}@media(max-width: 600px) {    .header {        padding: 25px 15px;    }    .header h1 {        font-size: 24px;        margin-top: 15px;    }    .back {        position: static;        display: inline-block;        margin-bottom: 12px;    }    .attendance-layout {        padding: 0 13px 30px;    }    .attendance-form,    .attendance-table {        padding: 17px;    }}</style></head><body><header class="header">    <a href="dashboard.php" class="back">        Back to Dashboard    </a>    <h1>Attendance Management</h1></header><div class="attendance-layout">    <!-- MARK ATTENDANCE FORM -->    <div class="attendance-form">        <h2>Mark Attendance</h2>        <?php if ($message !== ""): ?>            <div class="message <?php echo e($messageType); ?>">                <?php echo e($message); ?>            </div>        <?php endif; ?>        <form method="POST">            <label>Select Student</label>            <select name="student_id" required>                <option value="">Choose Student</option>                <?php if ($students): ?>                    <?php while ($student = pg_fetch_assoc($students)): ?>                    <option value="<?php echo (int)$student['student_id']; ?>">                        <?php echo e($student['roll_number'] . " - " . $student['student_name']); ?>                    </option>                    <?php endwhile; ?>                <?php endif; ?>            </select>            <label>Select Subject</label>            <select name="subject_id" required>                <option value="">Choose Subject</option>                <?php if ($subjects): ?>                    <?php while ($subject = pg_fetch_assoc($subjects)): ?>                    <option value="<?php echo (int)$subject['subject_id']; ?>">                        <?php echo e($subject['subject_name']); ?>                    </option>                    <?php endwhile; ?>                <?php endif; ?>            </select>            <label>Select Teacher</label>            <select name="teacher_id" required>                <option value="">Choose Teacher</option>                <?php if ($teachers): ?>                    <?php while ($teacher = pg_fetch_assoc($teachers)): ?>                    <option value="<?php echo (int)$teacher['teacher_id']; ?>">                        <?php echo e($teacher['teacher_name']); ?>                    </option>                    <?php endwhile; ?>                <?php endif; ?>            </select>            <label>Attendance Date</label>            <input type="date"            name="attendance_date"            value="<?php echo date('Y-m-d'); ?>"            required>            <label>Attendance Status</label>            <select name="status" required>                <option value="">Select Status</option>                <option value="Present">Present</option>                <option value="Absent">Absent</option>            </select>            <button type="submit"            name="mark_attendance"            class="save-btn">                Save Attendance            </button>        </form>    </div>    <!-- ATTENDANCE RECORDS -->    <div class="attendance-table">        <h2>Attendance Records</h2>        <div class="table-responsive">            <table>                <tr>                    <th>ID</th>                    <th>Roll No.</th>                    <th>Student</th>                    <th>Subject</th>                    <th>Teacher</th>                    <th>Date</th>                    <th>Status</th>                    <th>Action</th>                </tr>                <?php if ($records && pg_num_rows($records) > 0): ?>                    <?php while ($row = pg_fetch_assoc($records)): ?>                    <tr>                        <td><?php echo e($row['attendance_id']); ?></td>                        <td><?php echo e($row['roll_number']); ?></td>                        <td><?php echo e($row['student_name']); ?></td>                        <td><?php echo e($row['subject_name']); ?></td>                        <td><?php echo e($row['teacher_name']); ?></td>                        <td><?php echo e($row['attendance_date']); ?></td>                        <td class="<?php echo strtolower(e($row['status'])); ?>">                            <?php echo e($row['status']); ?>                        </td>                        <td>                            <a class="edit-btn"                            href="edit_attendance.php?id=<?php echo (int)$row['attendance_id']; ?>">                                Edit                            </a>                        </td>                    </tr>                    <?php endwhile; ?>                <?php else: ?>                    <tr>                        <td colspan="8" class="empty">                            No attendance records found.                        </td>                    </tr>                <?php endif; ?>            </table>        </div>    </div></div></body></html>